/* BA-first curriculum. Examples and rules are fictional and require stakeholder validation. */
const baLessonSource='https://www.iiba.org/knowledgehub/the-business-analysis-standard/4-implementing-business-analysis/4-4-understanding-requirements-and-designs/';
requestJourneySteps.splice(0,requestJourneySteps.length,
{name:'Nhu cầu & đầu vào',subtitle:'Ai cần gì, vì sao?',title:'Bắt đầu từ nhu cầu đặt hàng của khách.',body:'Tình huống giả lập: khách muốn đặt 2 sản phẩm và biết chắc yêu cầu đã được tiếp nhận. BA cần xác định mục tiêu, phạm vi, tác nhân, điều kiện trước và dữ liệu cần cung cấp. Chưa chọn công nghệ hay thiết kế hạ tầng ở bước này.',takeaway:'Một màn hình có nút “Đặt hàng” chưa đủ để mô tả yêu cầu. Cần làm rõ ai dùng, nhu cầu gì và kết quả nào mang lại giá trị.',question:'Stakeholder nói “cho tôi một form đặt hàng”. BA cần làm gì tiếp?',answer:'Hỏi mục đích và vấn đề hiện tại, ai sử dụng, trường hợp nào cần đặt hàng, dữ liệu nào thật sự cần, ai sở hữu dữ liệu và kết quả mong đợi. Sau đó xác nhận phạm vi bằng ví dụ cụ thể thay vì chốt ngay các ô trên form.',events:['Khách nhập thông tin và chọn sản phẩm','BA làm rõ nhu cầu và dữ liệu bắt buộc'],terms:['Stakeholder','User story','Data dictionary'],source:baLessonSource,questions:['Ai được đặt hàng: khách vãng lai hay phải đăng nhập?','Có thể đặt nhiều địa chỉ giao hàng trong một đơn không?','Số điện thoại dùng để giao hàng hay để định danh tài khoản?'],artifact:'US-01: Là khách hàng, tôi muốn gửi đơn mua sản phẩm để nhận xác nhận và theo dõi đơn của mình.',rule:'Đề xuất cần xác nhận: mỗi dòng hàng cần mã sản phẩm và số lượng là số nguyên dương; thông tin liên hệ chỉ thu thập theo nhu cầu giao hàng.',acceptance:'Given khách đã chọn sản phẩm\nWhen nhập số lượng bằng 0 và bấm Đặt hàng\nThen form chỉ rõ lỗi tại trường số lượng và không tạo đơn.',exercise:'Viết 5 trường dữ liệu đầu vào. Với từng trường, nêu kiểu dữ liệu, bắt buộc/không bắt buộc và người xác nhận quy tắc.'},
{name:'Quy tắc nghiệp vụ',subtitle:'Điều kiện và ngoại lệ',title:'Xác định điều gì làm một đơn hàng hợp lệ.',body:'Sau khi nhận dữ liệu, hệ thống cần kiểm tra điều kiện đặt hàng: số lượng, vùng giao hàng, giá, tồn khả dụng và ưu đãi. BA phân biệt quy tắc nghiệp vụ với kiểm tra định dạng; ghi rõ nguồn quy tắc, người phê duyệt và hành vi khi không đạt.',takeaway:'Giá, tồn kho và quyền đặt hàng phải được kiểm tra ở nơi xử lý nghiệp vụ có thẩm quyền; thông tin trên giao diện không thay thế được bước xác nhận này.',question:'Form báo còn hàng nhưng lúc gửi đơn chỉ còn 1 trong 2 sản phẩm thì sao?',answer:'Đây là ngoại lệ cần quyết định nghiệp vụ. Hỏi người có thẩm quyền có cho đặt một phần, yêu cầu khách xác nhận lại hay từ chối toàn bộ. Không tự chọn thay stakeholder và không âm thầm đổi số lượng.',events:['Gửi dữ liệu để kiểm tra điều kiện','Đối chiếu giá, tồn và thông tin liên quan'],terms:['Business rule','Decision table','Exception flow'],source:baLessonSource,questions:['Giá được chốt khi thêm giỏ, gửi đơn hay xác nhận thanh toán?','Tồn kho không đủ thì từ chối toàn đơn hay cho đặt một phần?','Hai ưu đãi có được áp dụng đồng thời không?'],artifact:'BR-01: Số lượng mua không vượt tồn khả dụng tại thời điểm xác nhận. BR-02: Nếu giá thay đổi, cần khách chấp nhận giá mới trước khi tiếp tục. Cả hai là quy tắc giả lập cần được duyệt.',rule:'Decision table cần có điều kiện đầu vào, kết quả, thứ tự ưu tiên và trường hợp mặc định; tránh để hai quy tắc tạo ra kết quả mâu thuẫn.',acceptance:'Given khách yêu cầu 2 sản phẩm nhưng tồn khả dụng chỉ là 1\nWhen kiểm tra điều kiện đặt hàng\nThen không tạo đơn đã xác nhận, hiển thị sản phẩm thiếu và yêu cầu khách điều chỉnh giỏ. Đây là ví dụ khi chính sách từ chối toàn đơn đã được duyệt.',exercise:'Lập bảng quyết định gồm tồn đủ/thiếu và giá giữ nguyên/thay đổi. Mô tả hành vi cho cả 4 tổ hợp.'},
{name:'Tích hợp hệ thống',subtitle:'Dữ liệu gửi đi, nhận về',title:'Làm rõ thỏa thuận giữa các hệ thống.',body:'Trong tình huống này, ứng dụng bán hàng gọi dịch vụ đơn hàng và nhận kết quả từ hệ thống kho. BA mô tả dữ liệu trao đổi, ý nghĩa trường, điều kiện thành công và xử lý lỗi. Đội kỹ thuật quyết định cách triển khai phù hợp với các yêu cầu đã thống nhất.',takeaway:'Timeout chỉ cho biết chưa nhận được kết quả trong thời hạn chờ; không đủ để kết luận nghiệp vụ đã thất bại.',question:'Khách bấm lại sau timeout: có được tạo thêm đơn không?',answer:'BA cần xác định yêu cầu tránh tạo trùng cho cùng thao tác, thời gian bảo vệ, cách tra cứu trạng thái và hành vi khi không thể xác minh. Trao đổi với đội kỹ thuật về cơ chế phù hợp; không hứa mọi lần gửi lại đều an toàn nếu chưa có thiết kế hỗ trợ.',events:['Ứng dụng gửi yêu cầu tạo đơn','Dịch vụ đơn hàng trao đổi với hệ thống kho'],terms:['API contract','Field mapping','Timeout & retry'],source:baLessonSource,questions:['Mã khách, mã sản phẩm và đơn vị số lượng ở hai hệ thống có giống nhau không?','Nếu không nhận phản hồi, ai tra cứu kết quả và khi nào báo khách?','Bấm lại cùng thao tác có tạo giao dịch mới hay dùng lại kết quả cũ?'],artifact:'Ví dụ dữ liệu gửi: customerId, items[{productId, quantity}], deliveryAddress, requestId. Dữ liệu nhận: orderId, businessStatus, message. Đây là ví dụ hợp đồng dữ liệu, không phải API thật.',rule:'Phân biệt lỗi dữ liệu, lỗi nghiệp vụ và lỗi kết nối. Với mỗi loại, nêu thông báo cho người dùng, khả năng thử lại, người chịu trách nhiệm và thông tin cần truy vết.',acceptance:'Given yêu cầu tạo đơn đã được tiếp nhận nhưng phản hồi bị timeout\nWhen khách gửi lại cùng thao tác trong phạm vi chống trùng đã thống nhất\nThen không tạo đơn thứ hai và hệ thống trả hoặc tra cứu trạng thái của yêu cầu ban đầu.',exercise:'Viết bảng mapping 4 trường dữ liệu và 3 trường hợp lỗi. Mỗi lỗi cần có hành vi màn hình và cách xử lý tiếp theo.'},
{name:'Trạng thái & UAT',subtitle:'Chứng minh đúng nghiệp vụ',title:'Kết thúc bằng kết quả kiểm chứng được.',body:'Khách cần biết đơn đang chờ, được xác nhận hay không thể thực hiện. BA định nghĩa ý nghĩa từng trạng thái, chuyển trạng thái hợp lệ, quyền thao tác và bằng chứng. Kết quả nhận được cần liên kết với yêu cầu ban đầu và bộ kịch bản UAT.',takeaway:'HTTP 200 hoặc thông báo “gửi thành công” không tự chứng minh đơn đã được xác nhận theo nghiệp vụ.',question:'Đã lưu đơn nghĩa là đơn đã sẵn sàng giao chưa?',answer:'Không nhất thiết. Phải xem trạng thái nghiệp vụ và các điều kiện như xác nhận tồn hoặc thanh toán theo chính sách. BA cần thống nhất thuật ngữ “tiếp nhận”, “xác nhận”, “thanh toán” và “sẵn sàng giao”, tránh dùng chung chữ “thành công”.',events:['Ghi nhận đơn và trạng thái nghiệp vụ','Trả mã đơn cùng hướng dẫn theo dõi'],terms:['State transition','Acceptance criteria','UAT & traceability'],source:'https://cucumber.io/docs/gherkin/reference/',questions:['Điều kiện nào chuyển Chờ xác nhận sang Đã xác nhận?','Ai có quyền hủy đơn và trường hợp nào phải hoàn tiền?','Làm sao khách biết đang chờ xử lý thay vì tự bấm tạo lại?'],artifact:'Ví dụ state model: Chờ xác nhận → Đã xác nhận / Từ chối / Đã hủy. Điều kiện và quyền cho từng chuyển trạng thái phải được duyệt; đây chưa phải toàn bộ vòng đời giao hàng.',rule:'Lập RTM nối US-01 → BR-01/BR-02 → AC → UAT. Bao gồm happy path, thiếu hàng, đổi giá, timeout, gửi lặp và quyền xem đơn của người khác.',acceptance:'Given đơn đã được xác nhận\nWhen khách tra cứu mã đơn hợp lệ của mình\nThen xem được trạng thái và thông tin đã xác nhận; người không có quyền không xem được dữ liệu của đơn đó.',exercise:'Viết 5 kịch bản UAT và liên kết từng kịch bản với một yêu cầu hoặc quy tắc. Nêu điều kiện trước, dữ liệu thử và kết quả kỳ vọng.'}
);
