function renderBAArtifacts(copy){return `<div class="ba-artifacts"><section><h3>BA cần hỏi gì?</h3><ul>${copy.questions.map(q=>`<li>${escScale(q)}</li>`).join('')}</ul></section><section><h3>Đầu ra BA cần viết</h3><p>${escScale(copy.artifact)}</p></section><section class="ba-artifact-wide"><h3>Quy tắc & điều cần xác nhận</h3><p>${escScale(copy.rule)}</p></section><section class="ba-artifact-wide"><h3>Ví dụ acceptance criteria</h3><pre>${escScale(copy.acceptance)}</pre><p class="metadata">Cách diễn đạt Given / When / Then giúp nêu điều kiện trước, hành động và kết quả kỳ vọng.</p></section><section class="ba-artifact-wide ba-exercise"><h3>Bài tập thực hành</h3><p>${escScale(copy.exercise)}</p></section></div>`}
function BASectionNav(){return `<nav class="ba-section-nav" aria-label="Kỹ thuật cho BA"><a href="#/scale" data-scale-nav="home">${uiIcon('flow')}<b>Kỹ thuật cho BA</b></a><button data-nav="Thư viện bài học">Thư viện BA</button><button data-nav="Case study">Case study</button></nav>`}
function BASectionFooter(){return `<div class="ba-section-footer">Học để phân tích và trao đổi với đội kỹ thuật · Tình huống, dữ liệu và quy tắc trong bài là giả lập.</div>`}
function renderBAFocusHome(){return `<div class="request-journey ba-focus-home"><div class="journey-kicker">BUSINESS ANALYSIS · HỌC ĐỂ ÁP DỤNG</div><h1>Kỹ thuật vừa đủ cho BA.</h1><p class="ba-home-intro">Tập trung vào điều BA cần làm rõ, đặc tả và nghiệm thu. Bắt đầu bằng một luồng nghiệp vụ xuyên suốt, sau đó luyện qua case study.</p><article class="ba-feature-lesson"><span>BÀI HỌC TƯƠNG TÁC · 4 BƯỚC</span><h2>Phân tích luồng đặt hàng cho BA</h2><p>Từ nhu cầu khách hàng đến dữ liệu đầu vào, quy tắc, tích hợp và tiêu chí nghiệm thu.</p><a class="primary" href="#/how-request-travels/1" data-scale-nav="lesson" data-scale-slug="how-request-travels">Bắt đầu bài học</a></article><div class="ba-path-grid">${[['users','Khai thác & xác nhận','Stakeholder, câu hỏi khai thác, problem statement và phạm vi.','Thư viện bài học'],['file','Đặc tả & mô hình hóa','Business rule, data dictionary, state model và acceptance criteria.','Thư viện bài học'],['case','Thực hành & phỏng vấn','Vận dụng vào tình huống, giải thích lựa chọn và tự chấm theo rubric.','Case study']].map(([icon,title,desc,target])=>`<button data-nav="${target}">${uiIcon(icon)}<h3>${title}</h3><p>${desc}</p><span>Mở ${target.toLocaleLowerCase('vi')}</span></button>`).join('')}</div><section class="ba-scope-note"><h3>Phạm vi học đã điều chỉnh</h3><p>Nội dung chính gồm nhu cầu, stakeholder, yêu cầu, business rule, quy trình, dữ liệu, tích hợp ở mức đặc tả và UAT. Kiến trúc hạ tầng, thuật toán cân bằng tải, phân mảnh dữ liệu và tối ưu CPU không thuộc lộ trình BA mặc định.</p></section><details class="ba-advanced"><summary>Tham khảo kỹ thuật nâng cao — tùy chọn</summary><p>Dành cho khi dự án cần trao đổi sâu với kỹ sư hoặc kiến trúc sư. Không phải bài BA cốt lõi và không có điều kiện buộc phải hoàn thành.</p><div>${scaleModulesData.map(m=>`<details><summary>${escScale(m.titleVi||m.title)}</summary>${m.lessons.filter(l=>l.slug!=='how-request-travels').map(l=>`<a href="#/${l.slug}/1" data-scale-nav="lesson" data-scale-slug="${l.slug}">${escScale(l.titleVi||l.title)}</a>`).join('')}</details>`).join('')}</div></details></div>`}
function BARequestCatalogue(){return `<nav class="ba-request-catalog" aria-label="Nội dung cho BA"><b>Luyện theo đầu ra công việc</b><button data-nav="Thư viện bài học">Ôn yêu cầu, quy trình và dữ liệu</button><button data-nav="Case study">Làm case study có hướng giải</button><button data-nav="Phỏng vấn">Luyện trình bày quyết định BA</button><a href="#/scale" data-scale-nav="home">Về Kỹ thuật cho BA</a></nav>`}
